import jdk.nashorn.api.scripting.AbstractJSObject;
import org.wso2.carbon.identity.application.common.model.ClaimMapping;

import java.util.Map;

/**
 * Javascript wrapper providing array-like access to a set of user claims, keyed by a claim URI.
 * The URI used to key the claims is resolved from the underlying {@link ClaimMapping} via the given
 * {@link IdMapper} (e.g. the local claim URI or the remote claim URI).
 * <p>
 * This provides controlled access to a {@code Map&lt;ClaimMapping, String&gt;} via provided javascript native syntax.
 * e.g
 * var email = context.subject.claims.local["http://wso2.org/claims/emailaddress"]
 * context.subject.claims.local["http://wso2.org/claims/emailaddress"] = "user@example.com"
 */
public class JsClaimView extends AbstractJSObject {

    private final Map<ClaimMapping, String> wrapped;
    private final IdMapper idMapper;

    public JsClaimView(Map<ClaimMapping, String> wrapped, IdMapper idMapper) {

        this.wrapped = wrapped;
        this.idMapper = idMapper;
    }

    @Override
    public Object getMember(String name) {

        if (wrapped == null || name == null) {
            return null;
        }
        for (Map.Entry<ClaimMapping, String> entry : wrapped.entrySet()) {
            String id = idMapper.toId(entry.getKey());
            if (name.equals(id)) {
                return entry.getValue();
            }
        }
        return null;
    }

    @Override
    public void setMember(String name, Object value) {

        if (wrapped == null || name == null) {
            return;
        }
        for (Map.Entry<ClaimMapping, String> entry : wrapped.entrySet()) {
            String id = idMapper.toId(entry.getKey());
            if (name.equals(id)) {
                entry.setValue(value != null ? String.valueOf(value) : null);
                return;
            }
        }
    }

    @Override
    public boolean isArray() {

        return true;
    }

    /**
     * Resolves the identifier (claim URI) used to key a claim from the given {@link ClaimMapping}.
     */
    public interface IdMapper {

        /**
         * Extracts the URI used to identify the given claim mapping.
         *
         * @param claimMapping the claim mapping to extract the URI from.
         * @return the claim URI.
         */
        String toId(ClaimMapping claimMapping);
    }
}
