package org.wso2.carbon.identity.application.authentication.framework.config.model.graph.js;

import jdk.nashorn.api.scripting.JSObject;
import org.wso2.carbon.identity.application.authentication.framework.util.FrameworkConstants;
import org.wso2.carbon.identity.application.common.model.ClaimMapping;

import java.util.Map;
import java.util.function.Consumer;

/**
 * Javascript wrapper for a set of user claims held as a {@code Map&lt;ClaimMapping, String&gt;}.
 * This provides controlled access to the user attributes of an authenticated subject via provided javascript native
 * syntax.
 * e.g
 * var email = context.subject.claims.local["http://wso2.org/claims/emailaddress"]
 * context.subject.claims.push({local: "...", remote: "...", value: "..."})
 *
 * @see JsClaimView
 * @see ClaimMapping
 */
public class JsClaimSet extends AbstractJSObjectWrapper<Map<ClaimMapping, String>> {

    private static final JsLogger LOG = JsLogger.getInstance();

    public JsClaimSet(Map<ClaimMapping, String> wrapped) {
        super(wrapped);
    }

    @Override
    public Object getMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
                return new JsClaimView(getWrapped(), claimMapping ->
                        claimMapping.getLocalClaim() != null ? claimMapping.getLocalClaim().getClaimUri() : null);
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
                return new JsClaimView(getWrapped(), claimMapping ->
                        claimMapping.getRemoteClaim() != null ? claimMapping.getRemoteClaim().getClaimUri() : null);
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return (Consumer<Object>) this::push;
            default:
                return super.getMember(name);
        }
    }

    @Override
    public boolean hasMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return true;
            default:
                return super.hasMember(name);
        }
    }

    /**
     * Builds a new {@link ClaimMapping} from the given claim object and inserts it into the wrapped user attributes.
     * The claim object is expected to contain {@code local}, {@code remote} and {@code value} fields. If the
     * {@code value} field is missing, no entry is added.
     *
     * @param claim the claim object pushed from javascript.
     */
    public void push(Object claim) {

        Object local = getClaimMember(claim, FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL);
        Object remote = getClaimMember(claim, FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE);
        Object value = getClaimMember(claim, FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_VALUE);

        if (local == null || remote == null) {
            LOG.error("Cannot push claim. Both 'local' and 'remote' claim URIs are required.");
            return;
        }
        if (value == null) {
            LOG.error("Cannot push claim. The 'value' field is required for claim: " + String.valueOf(local));
            return;
        }

        ClaimMapping claimMapping = ClaimMapping.build(String.valueOf(local), String.valueOf(remote), null, false);
        getWrapped().put(claimMapping, String.valueOf(value));
    }

    /**
     * Returns true if there are no claims in the wrapped user attributes.
     *
     * @return true if the user attributes map is empty.
     */
    public boolean isEmpty() {

        return getWrapped().isEmpty();
    }

    private Object getClaimMember(Object claim, String member) {

        if (claim instanceof Map) {
            return ((Map) claim).get(member);
        }
        if (claim instanceof JSObject) {
            JSObject jsObject = (JSObject) claim;
            if (jsObject.hasMember(member)) {
                return jsObject.getMember(member);
            }
            return null;
        }
        return null;
    }
}
